class Solution {
public:
    long long maxScore(vector<int>& nums) {
        int n = nums.size();
        vector<long long> dp(n, LLONG_MIN / 4);
        dp[n - 1] = 0;
        for (int i = n - 2; i >= 0; --i)
            for (int j = i + 1; j < n; ++j)
                dp[i] = max(dp[i], dp[j] + (long long)(j - i) * nums[j]);
        return dp[0];
    }
};
